enum MathError: Error {
    case divideByZero
}
func divide(_ a: Int, by b: Int) throws -> Int {
    if b == 0 { throw MathError.divideByZero }
    return a / b
}
let result = try? divide(10, by: 0)
print(result == nil)

enum SimpleError: Error {
    case failure
}
func checkNumber(_ n: Int) throws -> String {
    if n < 0 { throw SimpleError.failure }
    return "Positive"
}
do {
    let msg = try checkNumber(5)
    print(msg)
} catch {
    print("Failed")
}

func executeTask() {
    defer { print("Third") }
    defer { print("Second") }
    print("First")
}
executeTask()

enum AuthError: Error {
    case invalidToken
}
let outcome: Result<String, AuthError> = .failure(.invalidToken)
switch outcome {
case .success(let token):
    print("Token: \(token)")
case .failure:
    print("Authentication failed")
}

enum LoadError: Error {
    case timeout
}
func load() throws -> Int {
    throw LoadError.timeout
}
let value = (try? load()) ?? 42
print(value)

enum ServerError: Error {
    case notFound(code: Int)
}
func request() throws {
    throw ServerError.notFound(code: 404)
}
do {
    try request()
} catch ServerError.notFound(let code) {
    print("Status code: \(code)")
} catch {
    print("General error")
}

enum CalcError: Error {
    case negative
}
let res: Result<Int, CalcError> = .success(25)
let num = try? res.get()
print(num ?? 0)

enum StepError: Error {
    case failed
}
func step() throws {
    defer { print("Step cleanup") }
    throw StepError.failed
}
do {
    try step()
} catch {
    print("Handled error")
}

